int frontend_parse_map_fold_num(struct frontend_parse_Stmt * self, int n, long * out) {
    struct runtime_arena_Node * nd;
    long a;
    long b;
    if (n < 0) {
        return 0;
    }
    nd = (&self->arena->nodes[n]);
    if (nd->kind == N_NUM) {
        (*out) = nd->num;
        return 1;
    }
    if (nd->kind == N_UNARY) {
        if ((!frontend_parse_map_fold_num(self, nd->a, (&a)))) {
            return 0;
        }
        if (nd->aux == 1) {
            (*out) = (-a);
            return 1;
        }
        if (nd->aux == 2) {
            (*out) = (!a);
            return 1;
        }
        if (nd->aux == 3) {
            (*out) = (~a);
            return 1;
        }
        return 0;
    }
    if (nd->kind != N_BIN) {
        return 0;
    }
    if (((!frontend_parse_map_fold_num(self, nd->a, (&a))) || (!frontend_parse_map_fold_num(self, nd->b, (&b))))) {
        return 0;
    }
    if (((a < (-1099511627776L)) || (a > 1099511627776L))) {
        return 0;
    }
    if (((b < (-1099511627776L)) || (b > 1099511627776L))) {
        return 0;
    }
    switch (nd->aux) {
        case B_ADD:
            (*out) = (a + b);
            break;
        case B_SUB:
            (*out) = (a - b);
            break;
        case B_MUL:
            if (((a < (-2147483647L)) || (a > 2147483647L))) {
                return 0;
            }
            if (((b < (-2147483647L)) || (b > 2147483647L))) {
                return 0;
            }
            (*out) = (a * b);
            break;
        case B_DIV:
            if (b == 0) {
                return 0;
            }
            (*out) = (a / b);
            break;
        case B_MOD:
            if (b == 0) {
                return 0;
            }
            (*out) = (a % b);
            break;
        case B_SHL:
            if (((b < 0) || (b > 20))) {
                return 0;
            }
            if (((a < (-524288L)) || (a > 524288L))) {
                return 0;
            }
            (*out) = (a << b);
            break;
        case B_SHR:
            if (((b < 0) || (b > 40))) {
                return 0;
            }
            (*out) = (a >> b);
            break;
        case B_BAND:
            (*out) = (a & b);
            break;
        case B_BOR:
            (*out) = (a | b);
            break;
        case B_XOR:
            (*out) = (a ^ b);
            break;
        default:
            return 0;
    }
    return 1;
}
